## 4. Practical code upgrades

Below are code snippets that you can *paste* into `app.js` (or split into separate modules) to tighten security even before the codebase grows.

### 4.1. Install the required packages

```bash
npm install helmet express-rate-limit express-validator
# (If you use a database later, add `yarn add objection pg` etc.)
```

### 4.2. Security middleware

```js
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ---- 1) Security headers ----
app.use(helmet({
  // Disable the 'X-Powered-By' header
  hidePoweredBy: true,

  // CSP example – no inline scripts allowed
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
    },
  },
}));

// ---- 2) Rate limiting ----
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---- 3) JSON body parser (if needed later) ----
app.use(express.json());
// ---------------------------
```

### 4.3. Basic auth guard for `/users`

For demonstration, we’ll use a simple API‑key check that should transition to a proper auth system downstream.

```js
// =====================================================
// Simple API‑Key auth middleware
// =====================================================
const AUTH_TOKEN = process.env.AUTH_TOKEN || 's3cr3t-key';

function requireAuth(req, res, next) {
  const apiKey = req.header('X-Api-Key');
  if (!apiKey || apiKey !== AUTH_TOKEN) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}
```

Now protect the route:

```js
app.get('/users', requireAuth, (req, res) => {
  // (Same payload as before)
});
```

### 4.4. Global error handler

```js
// Catch all unhandled errors
app.use((err, req, res, next) => {
  console.error('Unhandled error', err);
  // Do NOT expose stack trace to clients in production
  res.status(500).json({ error: 'Internal Server Error' });
});
```

### 4.5. Logging (optional but recommended)

```bash
npm install morgan
```

```js
const morgan = require('morgan');
app.use(morgan('combined')); // or 'dev' for less verbose output
```

