## Suggested Refactored `app.js`

```js
// app.js – production‑ready baseline
require('dotenv').config();          // Load .env vars

const express = require('express');
const helmet = require('helmet');
const cors   = require('cors');
const { createLogger, transports, format } = require('winston');
const enforce = require('express-enforces-ssl');
const rateLimit = require('express-rate-limit');

const app = express();
const logger = createLogger({
  level: 'info',
  format: format.combine(format.timestamp(), format.json()),
  transports: [new transports.Console()],
});

app.set('logger', logger);

// 1️⃣ HTTP security headers
app.use(helmet());

// 2️⃣ CORS policy
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*',   // tighten in prod
  credentials: true
}));

// 3️⃣ Rate limiting
app.use(rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 200
}));

// 4️⃣ HTTPS enforcement in production
if (process.env.NODE_ENV === 'production') app.use(enforce.HTTPS({ trustProtoHeader: true }));

// 5️⃣ Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([ // this would normally be protected via auth
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// 6️⃣ 404
app.use((req, res) => res.status(404).json({ error: 'Not Found' }));

// 7️⃣ Global error handler
app.use((err, req, res, next) => {
  logger.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => logger.info(`Server running on port ${PORT}`));

module.exports = app;
```

> **Note**: The above file is only a *baseline*. Real production systems will need further hardening:
> * Store secrets (JWT secret, db password) in a vault or KMS, not in `.env`.  
> * Add role‑based access control for `/users`.  
> * If database access is added, enforce parameterised queries.  
> * Rotate TLS certificates and/or enforce HSTS.  
> * Enable `helmet.frameguard()` with a proper value to prevent click‑jacking.  

Feel free to cherry‑pick the sections above that address your particular threat model. If you need assistance wiring up JWT, or adding more routes safely, let me know!

