      status: 'unhealthy',
      errors: ['Database unreachable'],
      timestamp: new Date().toISOString(),
    });
  }
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});
```

### 3.5 Basic Authentication Middleware (JWT Example)

```js
const jwt = require('jsonwebtoken');
const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret';

function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader) return res.status(401).json({ error: 'No token' });

  const token = authHeader.split(' ')[1]; // Bearer <token>
  if (!token) return res.status(401).json({ error: 'Malformed token' });

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user; // attach user's payload
    next();
  });
}
```

Protect the `/users` route:

```js
app.get('/users', requireAuth, async (req, res) => {
  // Real DB call here
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Optionally mask IRIs or fields
  const sanitized = users.map(u => ({ id: u.id, name: u.name }));
  res.json(sanitized);
});
```

> **Tip:** If you are not ready to expose the JWT secret publicly, store it (and the DB password, etc.) in `process.env` via a `.env` file.

