const { query, validationResult } = require('express-validator');

app.get('/search',
  // Example: a `q` query param must be UTF‑8 and ≤64 chars
  query('q')
    .isLength({ min: 1, max: 64 })
    .isAscii()
    .trim()
    .escape(),   // Basic XSS protection
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
