], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()){
    return res.status(400).json({ errors: errors.array() });
  }
  // fetch user by ID ...
});
```

This prevents injection attacks such as unsanitized IDs being concatenated into queries.

