app.use((req, res, next) => {
  logger.info({ method: req.method, path: req.originalUrl, ip: req.ip });
  next();
});
```

**Why?**  
From a security view, you can audit requests, detect anomalies, and correlate logs with monitoring dashboards.

### 3.5 Error Handling Middleware

```js
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log internal details
  logger.error(err);

  // Hide stack traces from clients
  res.status(err.statusCode || 500).json({
    message: err.message || 'Internal Server Error',
  });
});
```

**Why?**  
Avoids leaking stack traces and environment hints that an attacker could use.

### 3.6 CORS Policy (if the API is consumed cross‑origin)

```js
const cors = require('cors');

// Only allow requests from your trusted client
app.use(
  cors({
    origin: 'https://yourclient.example.com',
    credentials: true, // If you need cookies
  })
);
```

**Why?**  
Blocks bearer token or session cookie theft via unauthorized origins.

