### 3.1. Security headers with **helmet**

```js
// 1️⃣ Add the dependency
// npm install helmet
const helmet = require('helmet');

// 2️⃣ Add it early, before defining routes
app.use(helmet());

// 3️⃣ Customise for stricter policy (example)
app.use(
  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'sha256-XYZ'" ], // whitelist allowed scripts
      // ... more
    },
  })
);
```

`helmet` sets `X-Frame-Options`, `X-Content-Type-Options`, `Strict-Transport-Security`, `Content-Security-Policy`, and others.  
You can also set `helmet.hidePoweredBy()` (already part of `helmet`) to remove the Express banner.

### 3.2. HTTPS / HSTS

If you run this in production behind a reverse‑proxy (nginx, traefik, etc.) you typically let the proxy handle TLS.  
In a pure Node setup you can:

```js
// npm install https @types/https
const https = require('https');
const fs = require('fs');
const path = require('path');

const options = {
  key: fs.readFileSync(path.join(__dirname, 'certs', 'privkey.pem')),
  cert: fs.readFileSync(path.join(__dirname, 'certs', 'cert.pem')),
};

https.createServer(options, app).listen(8443, () => {
  console.log('HTTPS Server running on port 8443');
});
```

Add the `HSTS` header via helmet:

```js
app.use(
  helmet.hsts({
    maxAge: 60 * 60 * 24 * 365, // 1 year
    includeSubDomains: true,
    preload: true,
  })
);
```

### 3.3. Rate limiting – **express‑rate‑limit**

```js
// npm install express-rate-limit
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 200, // limit each IP to 200 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply to all requests
app.use(limiter);
```

If you later add sensitive endpoints (login, sign‑up), scale the limits or apply additional dedicated limits.

### 3.4. Body‑parsing & Input validation (hypothetical POST route)

You will eventually add POST endpoints, but here's how you can guard against malformed bodies & injection before you do:

```js
// npm install express-validator
const { body, validationResult } = require('express-validator');

app.use(express.json()); // parse JSON bodies

app.post(
  '/signup',
  body('email').isEmail().normalizeEmail(),
  body('password').isStrongPassword(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // safe to use req.body.email, req.body.password
    // ... signup logic
  }
);
```

Schema‑based parsing (e.g. `zod` or `joi`) is also an excellent alternative.

### 3.5. Logging & error handling

```js
// npm install pino-multi-stream
const pino = require('pino');
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });
app.locals.logger = logger;

// Centralised error‑handler middleware
app.use((err, req, res, next) => {
  logger.error(err);               // ship to Sentry, Loggly, etc.
  res.status(err.status || 500).json({
    message: process.env.NODE_ENV === 'production' ? 'Server error' : err.message,
  });
});
```

Make sure you **don’t** expose stack traces or internal details in production. Use `NODE_ENV=production` flag.

### 3.6. Future‑proofing – SQL injection guard

Even though you have no database now, add a simple example for future reference:

```js
// npm install pg
const { Pool } = require('pg');
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

app.get('/users/:id', async (req, res, next) => {
  try {
    const { rows } = await pool.query('SELECT id, name, email FROM users WHERE id = $1', [
      req.params.id,
    ]);
    res.json(rows);
  } catch (e) {
    next(e);
  }
});
```

Notice the use of a parameterized query (`$1`). Never build SQL directly with string concatenation.

