#### 3.1 Add Security Middleware

```js
// app.js
const express = require('express');
const helmet = require('helmet');          // HTTP headers security
const cors = require('cors');             // Cross‑Origin Resource Sharing
const rateLimit = require('express-rate-limit'); // DOS protection

const app = express();

// Basic Helmet configuration
app.use(helmet());

// Allow CORS only from a whitelist (adjust in production)
app.use(cors({ origin: 'https://your-domain.com' }));

// Simple rate limiter – 100 requests per 15 min per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// The rest of the app ...
```

> **Why?**  
> • `helmet` sets important headers (`X‑Content‑Type‑Options`, `X‑Frame‑Options`, `Strict-Transport-Security`, etc.).  
> • `cors` ensures only trusted origins can make browser‑initiated requests.  
> • Rate‑limiting reduces the risk of brute forcing or DDoS.

#### 3.2 Secure the Health Endpoint

Health checks are often exposed to internal monitoring only. You can restrict it to localhost or a specific header token.

```js
app.get('/health', (req, res) => {
  // Allow only from internal IPs or requests that carry a special header
  const allowed = req.ip === '127.0.0.1' || req.headers['x-health-check'] === 'secret-key';
  if (!allowed) return res.sendStatus(403);

  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

#### 3.3 Hide Sensitive Data in `/users`

Even if the users are fake, never expose private info. If you eventually populate this from a DB, sanitize output:

```js
app.get('/users', (req, res) => {
  // In a real app, you’d query a DB and project only allowed fields:
  // SELECT id, name FROM users;

  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});
```

> **Tip:** Use a DTO layer or library like `class-transformer` to control serialization.

#### 3.4 Add TLS/HTTPS

At the application level you can’t enforce HTTPS, but you can configure Express to trust the `X‑Forwarded‑Proto` header when behind a reverse proxy:

```js
app.set('trust proxy', 1); // trusting the first proxy (e.g., nginx)

app.use((req, res, next) => {
  if (req.secure || req.get('x-forwarded-proto') === 'https') {
    return next();
  }
  // In production (behind HTTPS), redirect
  res.redirect(`https://${req.headers.host}${req.url}`);
});
```

> **Important**: In staging or production, place a real TLS termination at the load balancer or reverse proxy.

#### 3.5 Prepare for Authentication

Even if not required now, placeholder for JSON Web Token (JWT):

```js
const jwt = require('jsonwebtoken');
const AUTH_SECRET = process.env.AUTH_SECRET ?? 'dev-secret';

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>
  if (!token) return res.sendStatus(401);

  jwt.verify(token, AUTH_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
}

// Example protected route
app.get('/profile', authenticateToken, (req, res) => {
  res.json({ id: req.user.id, name: req.user.name });
});
```

