### 3.2 Signature Security Stack

If you anticipate growth (auth, DB, file uploads, etc.), start with this template next time you scaffold an API:

```js
// app.js
'use strict';

const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const morgan    = require('morgan');
const rateLimit = require('express-rate-limit');
const jwt       = require('express-jwt');
const jwksRsa   = require('jwks-rsa');   // if using Auth0/Okta
const { celebrate, Joi, errors } = require('celebrate'); // validation
const winston   = require('winston');
const app       = express();

const PORT = process.env.PORT || 3000;

// Winston logger
const logger = winston.createLogger({
  level: 'info',
  transports: [
    new winston.transports.Console({ format: winston.format.simple() })
  ]
});

// Built‑in request syscall logger
app.use(morgan('combined', { stream: { write: logger.info } }));

// json / urlencoded body parsers
app.use(express.json());
app.use(express.urlencoded({ extended: false }));

app.use(helmet());

// CORS – Only allow known origins
app.use(cors({
  origin: ['https://app.example.com', 'http://localhost:3000'],
  credentials: true,
}));

// rate limiter
app.use(rateLimit({
  windowMs: 1 * 60 * 1000,
  max: 200,
  keyGenerator: (req) => req.ip,
}));

// -------------------------------------
// JWT Auth Middleware (sanitize & guard)
// -------------------------------------
app.use(jwt({
  secret: jwksRsa.expressJwtSecret({
    cache: true,
    rateLimit: true,
    jwksRequestsPerMinute: 5,
    jwksUri: `https://${process.env.AUTH0_DOMAIN}/.well-known/jwks.json`
  }),
  audience: process.env.AUTH0_AUDIENCE,
  issuer: `https://${process.env.AUTH0_DOMAIN}/`,
  algorithms: ['RS256']
}).unless({ path: ['/health', '/login'] })); // Permit open‑endpoints

// -------------------------------------
// Parameter validation with celebrate
// -------------------------------------
const userSchema = Joi.object({
  id:    Joi.number().integer().positive().required(),
  name:  Joi.string().max(50).required(),
  email: Joi.string().email().required()
});

app.get('/users',
  celebrate({
    query: Joi.object({
      limit: Joi.number().integer().min(1).max(100).default(10),
      offset: Joi.number().integer().min(0).default(0)
    })
  }),
  async (req, res) => {
    // Simulated query – replace with real DB calls
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com' },
    ];
    res.json(users.slice(req.query.offset, req.query.offset + req.query.limit));
  });

// -------------------------------------
// Error handling
// -------------------------------------
app.use(errors()); // celebrate validation errors

app.use((err, req, res, next) => {
  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({ error: 'Invalid token' });
  }
  logger.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

// -------------------------------------
// Launch
// -------------------------------------
app.listen(PORT, () => {
  logger.info(`Server listening on ${PORT}`);
});

module.exports = app;
```

**Highlights of this stack**

- **JWT/JWKS** – robust authentication with claims.  
- **Celebrate/Joi** – request payload validation.  
- **Winson + Morgan** – comprehensive logging.  
- **CSP & CSP‑related Helmet config** can be added (e.g., `helmet.contentSecurityPolicy({...})`).  
- **`express-jwt`** automatically fails request if no valid bearer token is supplied.  
- **`unless`** route whitelist lets you configure open endpoints easily.  

