```js
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');

app.post('/login', express.json(), async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: 'Missing credentials' });
  }

  // In real apps, fetch user record from DB
  const userRecord = { id: 1, username: 'alice', passwordHash: await bcrypt.hash('pw', 10) };

  const match = await bcrypt.compare(password, userRecord.passwordHash);
  if (!match) return res.status(401).json({ error: 'Invalid credentials' });

  const token = jwt.sign({ id: userRecord.id }, process.env.JWT_SECRET, { expiresIn: '1h' });
  res.json({ token });
});
```

* Uses `bcrypt` for hashing.  
* Gives a short‑lived JWT.  
