## 4.  Suggested Refactored `app.js`

Below is a **complete, hardened** version of the original file integrating most of the recommendations.

> **Important**: This file assumes the following environment variables are set:
> * `JWT_SECRET` – secret used to sign/verify JWT
> * `CORS_ORIGIN` – allowed CORS domain (e.g., `https://example.com`)

```js
// src/app.js
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const winston = require('winston');
const jwt = require('jsonwebtoken');

require('dotenv').config();           // loads .env variables

const app = express();

// --------------------- Security Middlewares --------------------- //
app.use(helmet()); // secure HTTP headers

// Enforce HTTPS (only if running behind a TLS listener)
app.use((req, res, next) => {
  if (!req.secure) return res.redirect(`https://${req.headers.host}${req.url}`);
  next();
});

// Strict CORS
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'https://example.com',
  methods: ['GET', 'POST', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 200,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Logging
app.use(morgan('combined'));
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [new winston.transports.Console()],
});

// --------------------- Helper Middlewares --------------------- //
const authenticate = (req, res, next) => {
  const header = req.headers.authorization;
  if (!header) return res.status(401).json({ error: 'Missing token' });

  const token = header.split(' ')[1];
  jwt.verify(token, process.env.JWT_SECRET, (err, payload) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = payload;
    next();
  });
};

// --------------------- Routes --------------------- //
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authenticate, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// --------------------- Error Handling --------------------- //
app.use((err, req, res, next) => {
  logger.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

// --------------------- Start Server --------------------- //
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

> **Breakdown of key changes:**
> * **Helmet** – adds `Content-Security-Policy`, `X-Frame-Options`, `X-Content-Type-Options`, etc.
> * **HTTPS redirect** – forces secure connection.
> * **CORS** – restricts allowed origins.
> * **Rate limiting** – protects endpoints from abuse.
> * **JWT authentication** – guards `/users`.
> * **Structured logging** – captures stack traces for audit.
> * **Error handler** – hides stack traces from clients.

